#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: what the owner does once so live scans check Google (issue #219,
# docs/adr/0023-google-results-are-bought-and-checked-from-one-point.md): open DataForSEO and
# Mapbox, keep their keys in 1Password, set them on the Worker, deploy, and measure what one
# Google keyword check costs on one organization of your own.
#
# Run it from the repository root, after the deploy that shipped Google results:
#   scripts/google-results-setup.sh
# It needs the 1Password CLI signed in to the Nearcited vault, and `gh`, `curl` and `jq`. The
# keys go from 1Password to the Worker and are never typed here or written to a file. The
# measurement is written to private/pricing/, which needs `npm run bootstrap:private` first.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=14

APP="https://nearcited.com"
DFS_LOGIN_REF="op://Nearcited/DataForSEO/login"
DFS_PASSWORD_REF="op://Nearcited/DataForSEO/api_password"
MAPBOX_REF="op://Nearcited/Mapbox/token"

# The DataForSEO account's balance in US dollars, asked of its free user_data endpoint. The
# sign-in is handed to curl on stdin, so it is never on a command line.
dfs_balance() {
  local login password
  login=$(op read "$DFS_LOGIN_REF") || return 1
  password=$(op read "$DFS_PASSWORD_REF") || return 1
  printf 'user = "%s:%s"\n' "$login" "$password" |
    curl -sS --config - "https://api.dataforseo.com/v3/appendix/user_data" |
    jq -er '.tasks[0].result[0].money.balance'
}

# What Mapbox says of the token in 1Password: TokenValid when it can be used. The token is
# handed to curl on stdin, so it is never on a command line.
mapbox_check() {
  local token
  token=$(op read "$MAPBOX_REF") || return 1
  printf 'url = "https://api.mapbox.com/tokens/v2?access_token=%s"\n' "$token" |
    curl -sS --config - | jq -r '.code // empty'
}

# Sets one Worker secret from 1Password, with the deploy credentials kept there too.
worker_secret() {
  local name="$1" ref="$2"
  if op read "$ref" |
    CLOUDFLARE_API_TOKEN="op://Nearcited/Cloudflare/api_token" \
    CLOUDFLARE_ACCOUNT_ID="op://Nearcited/Cloudflare/account_id" \
    op run -- npx -y pnpm@10.28.0 --filter @nearcited/api exec \
      wrangler secret put "$name" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name (Worker secret)")
    printf '  %s✓ set%s %s on the nearcited Worker\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Worker secret $name: op read $ref | pnpm --filter @nearcited/api exec wrangler secret put $name")
    warn "Could not set $name. It is listed at the end to do by hand."
  fi
}

banner "Google results: DataForSEO and Mapbox"

stage "Before you start"
say "Live scans check Google keywords once the Worker has three secrets: DataForSEO's API"
say "sign-in, which buys Google's results, and a Mapbox token, which finds the point each"
say "location is checked from. This opens both accounts, keeps the keys in 1Password, sets"
say "them on the Worker, deploys, and measures one scan on an organization of your own."
note "It costs: DataForSEO's minimum deposit of \$50, which does not expire; a card on Mapbox,"
note "which permanent geocoding needs; and a few cents of checks for the measurement."
for tool in op gh curl jq; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed. Install it and run this again."; exit 1; }
done
if ! op read "op://Nearcited/Cloudflare/account_id" >/dev/null 2>&1; then
  warn "The 1Password CLI cannot read the Nearcited vault. Sign it in and run this again."
  exit 1
fi
if [[ ! -d private/pricing ]]; then
  warn "private/ is not here, so the measurement cannot be written. Run npm run bootstrap:private."
  exit 1
fi
pause "Press Enter to begin"

stage "DataForSEO: open the account"
if op read "$DFS_LOGIN_REF" >/dev/null 2>&1; then
  note "1Password already has a DataForSEO sign-in. Skip this stage and the next two if the"
  note "account is open and funded."
fi
open_url "https://app.dataforseo.com/register"
step "Sign up with the business's email address, and confirm it from the email they send."
step "Sign in to the dashboard at app.dataforseo.com."
pause "Press Enter once you are signed in to the dashboard"

stage "DataForSEO: add funds"
say "Live checks are paid from a balance. A new account has \$1 of credit to try it."
step "In the dashboard, click Add Funds."
step "Choose \$50, the minimum, and pay. The balance does not expire."
pause "Press Enter once the payment has gone through"

stage "DataForSEO: keep the API sign-in in 1Password"
open_url "https://app.dataforseo.com/api-access"
say "API Access shows the API login and the API password. The API password is not the one you"
say "sign in to the dashboard with. It is shown for the first 24 hours after you register;"
say "after that, click Send by e-mail and it comes to your address."
step "In 1Password, in the Nearcited vault, make an item named DataForSEO."
step "Add a text field named login, holding the API login."
step "Add a password field named api_password, holding the API password."
pause "Press Enter once both fields are saved in 1Password"
while true; do
  if balance=$(dfs_balance 2>/dev/null); then
    printf '  %s✓%s DataForSEO answers to that sign-in. Balance: $%s\n' "$GREEN" "$RESET" "$balance"
    break
  fi
  warn "DataForSEO did not accept the sign-in in 1Password, or the fields are not named as above."
  confirm "Try again after fixing it?" || exit 1
done
pause "Press Enter to continue"

stage "DataForSEO: ask whether its results may be shown"
say "Their terms say the data must not be used to compete with search engines, and say nothing"
say "clear about showing results to your own customers. Ask in writing, and keep the answer."
say "Nothing below waits for it. Send something like:"
printf '\n'
note "  We run Nearcited, which tells local businesses where they appear in Google's map pack,"
note "  organic results, AI Overview and AI Mode for the searches they care about. We would buy"
note "  those results from your SERP API and show each subscriber the results for their own"
note "  business and keywords, inside our app. Is that allowed under your terms? We do not"
note "  resell the raw data or offer it as a data feed."
printf '\n'
open_url "https://dataforseo.com/contact"
pause "Press Enter once it is sent (or to send it later)"

stage "Mapbox: open the account"
open_url "https://account.mapbox.com/auth/signup/"
step "Sign up, or sign in if you already have an account."
step "Open the console's Billing page and add a payment method. Permanent geocoding, the kind"
step "whose results may be kept, is refused on an account without a card."
note "Mapbox's pages change: look for Billing in the account menu if it is not where you expect."
pause "Press Enter once a card is on the account"

stage "Mapbox: make the token and keep it in 1Password"
open_url "https://console.mapbox.com/account/access-tokens/"
step "Click Create a token. Name it Nearcited geocoding."
step "Leave the public scopes as they are, add no secret scope, and add no URL restriction:"
step "the Worker calls Mapbox from a server, which a URL restriction would turn away."
step "Create it and copy it (it starts with pk.)."
step "In 1Password, in the Nearcited vault, make an item named Mapbox with a password field"
step "named token, holding it."
pause "Press Enter once it is saved in 1Password"
while true; do
  code=$(mapbox_check 2>/dev/null || true)
  if [[ "$code" == "TokenValid" ]]; then
    printf '  %s✓%s Mapbox says the token is valid\n' "$GREEN" "$RESET"
    break
  fi
  warn "Mapbox did not take the token in 1Password (${code:-no answer})."
  confirm "Try again after fixing it?" || exit 1
done
pause "Press Enter to continue"

stage "Set the three secrets on the Worker"
say "This sets DATAFORSEO_LOGIN, DATAFORSEO_PASSWORD and MAPBOX_TOKEN on the deployed Worker,"
say "from 1Password, with the deploy credentials kept there. Google is checked only for an"
say "organization whose allowances include Google results, and no plan includes them yet, so"
say "nobody's scans change until the stages below give one organization of yours the allowance."
if confirm "Set the three secrets on the nearcited Worker now?"; then
  worker_secret DATAFORSEO_LOGIN "$DFS_LOGIN_REF"
  worker_secret DATAFORSEO_PASSWORD "$DFS_PASSWORD_REF"
  worker_secret MAPBOX_TOKEN "$MAPBOX_REF"
else
  SKIPPED+=("Worker secrets DATAFORSEO_LOGIN, DATAFORSEO_PASSWORD and MAPBOX_TOKEN")
fi
pause "Press Enter to continue"

stage "Deploy, so the Worker has the rates for Google's calls"
say "The rates each Google call is priced at, and the settings it is made with, are in the"
say "private tuning, which is bundled when the Worker is deployed. This runs the deploy"
say "workflow on main and waits for it and its smoke test."
if confirm "Deploy main now?"; then
  gh workflow run deploy.yml --ref main >/dev/null
  sleep 10
  run=$(gh run list --workflow deploy.yml --limit 1 --json databaseId -q '.[0].databaseId')
  note "Deploy run $run. This takes a few minutes."
  if gh run watch "$run" --exit-status >/dev/null 2>&1; then
    printf '  %s✓%s deployed, and the smoke test passed\n' "$GREEN" "$RESET"
  else
    warn "The deploy did not succeed. See: gh run view $run --log-failed"
    confirm "Carry on anyway?" || exit 1
  fi
else
  SKIPPED+=("Deploy main: gh workflow run deploy.yml --ref main")
fi
pause "Press Enter to continue"

stage "Give one organization of yours Google results"
say "Measure on an organization of your own that is not a test one: a test organization's"
say "scans are generated and buy nothing."
open_url "$APP/operator"
step "In the operator view, open your organization."
step "Open Plan and limits."
step "Under the allowances, tick Google results: map pack, organic, AI Overview and AI Mode."
step "Click Save limits. It takes effect at once."
pause "Press Enter once it is saved"

stage "Get a location ready"
step "Open one of that organization's locations, signed in as its owner."
step "Make sure its street address is filled in (Settings), so Google is checked from the door."
step "On Prompts, add a few Google keywords: Type → Google keyword, then Add keyword."
warn "Don't run a scan yet: the next stage reads DataForSEO's balance first, then asks for one."
ask KEYWORDS "How many active Google keywords does the location have now?"
until [[ "$KEYWORDS" =~ ^[1-9][0-9]*$ ]]; do ask KEYWORDS "Enter a whole number, 1 or more:"; done
ask PROMPTS "And how many active assistant prompts?"
until [[ "$PROMPTS" =~ ^[0-9]+$ ]]; do ask PROMPTS "Enter a whole number, 0 or more:"; done

stage "Measure one scan"
say "DataForSEO's balance is its own record of what it charged, so the difference across one"
say "scan is what that scan's Google checks cost. The assistants and Mapbox are billed"
say "elsewhere and do not move it."
while true; do
  if ! before=$(dfs_balance); then warn "Could not read the balance."; exit 1; fi
  note "Balance before: \$$before"
  step "On the location, click Run scan, and wait until the page shows the new results."
  step "Check the Google columns are filled in, and the line under the grid says where from."
  pause "Press Enter once the scan has finished"
  note "Waiting half a minute for the balance to catch up."
  sleep 30
  if ! after=$(dfs_balance); then warn "Could not read the balance."; exit 1; fi
  spent=$(jq -n --argjson b "$before" --argjson a "$after" '($b - $a) * 1e6 | round / 1e6')
  # A scan that checked Google always costs something, so nothing spent is not a reading.
  if jq -en --argjson s "$spent" '$s > 0' >/dev/null; then break; fi
  warn "The balance did not move, so no Google check was charged between the two readings."
  note "The scan may have run before the first reading, not have finished, or not have checked"
  note "Google: the location needs a Google keyword and the organization the allowance."
  confirm "Measure again with a new scan?" || exit 1
done
each=$(jq -n --argjson s "$spent" --argjson k "$KEYWORDS" '($s / $k) * 1e6 | round / 1e6')
note "Balance after: \$$after"
printf '  %s✓%s The scan cost \$%s at DataForSEO: \$%s for each of %s Google keywords.\n' \
  "$GREEN" "$RESET" "$spent" "$each" "$KEYWORDS"
note "DataForSEO's published live rates come to \$0.008 to \$0.012 a keyword: \$0.002 for the"
note "results page, \$0.002 for an AI Overview when there is one, \$0.002 for each 10 map"
note "results, and \$0.004 for AI Mode. Finding the point is Mapbox's, \$5 per 1,000 lookups."
pause "Press Enter to record it"

stage "Record it in the private pricing notes"
DAY=$(date -u +%F)
RECORD="private/pricing/${DAY}-what-a-google-check-costs.md"
if [[ -e "$RECORD" ]] && ! confirm "$RECORD exists. Replace it?"; then
  SKIPPED+=("The measurement: \$$spent for $KEYWORDS Google keywords, \$$each each")
else
  cat > "$RECORD" <<EOF
# What a Google check costs

Measured $DAY with \`scripts/google-results-setup.sh\` (public issue #219), on one real
location of the owner's own organization, given the \`google_results\` allowance for it.

One manual scan of a location with $KEYWORDS active Google keyword(s) and $PROMPTS active assistant
prompt(s), on the tuning's \`google\` settings as deployed. DataForSEO's balance, read from its
\`user_data\` endpoint, went from \$$before to \$$after: **\$$spent for the scan, \$$each for
each Google keyword**, for its four surfaces (results page with the AI Overview, Local Finder,
AI Mode).

Not in that figure: Mapbox's lookup of the location's point, made once and again only when the
address changes, at its published \$5 per 1,000; and the assistants' checks, which are priced
from their own rates.

To check against: DataForSEO's published live rates on 2026-10-17 come to \$0.008 to \$0.012 a
keyword (\$0.002 the results page, \$0.002 an AI Overview when there is one, \$0.002 for each 10
map results, \$0.004 AI Mode).

**One scan is one reading, not yet reviewed by the owner.** Whether an AI Overview appears, and
how many map results come back, changes from keyword to keyword.
EOF
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$RECORD"
  note "It is not committed. Ask Claude to read it, add its row to private/README.md and commit."
fi
pause "Press Enter to continue"

stage "Keep Google results on that organization, or not"
say "Every scheduled scan of that organization now checks its Google keywords, and each one is"
say "charged at DataForSEO. Keep it on to collect more readings, or take it off."
step "To take it off: operator view → your organization → Plan and limits → untick Google"
step "results → Save limits."
pause "Press Enter when you have decided"

finish
